def sign_invariant_quaternion_distance(q1: np.ndarray, q2: np.ndarray) -> float:
    """Computes sign-invariant Euclidean distance between two unit quaternions.
    
    Because q and -q represent the exact same SO(3) rotation:
        dist = min(||q1 - q2||, ||q1 + q2||)
    """
    a = np.asarray(q1, dtype=np.float64)
    b = np.asarray(q2, dtype=np.float64)
    diff_minus = np.linalg.norm(a - b)
    diff_plus = np.linalg.norm(a + b)
    return float(min(diff_minus, diff_plus))


